from itertools import combinations

_FIELDS = ('price', 'admin', 'promo', 'threshold', 'ship_subsidy', 'weight_threshold') + tuple(
    f'{prefix}_{i}'
    for prefix in ('item', 'restock', 'freight', 'weight')
    for i in range(6)
)
_EVENTS = tuple(s for k in range(1, 5) for s in combinations(range(6), k))


def assess(attrs):
    for name in _FIELDS:
        value = attrs.get(name)
        if type(value) is not int or value < 0:
            return {'feasible': False, 'utility': None}

    price = attrs['price']
    promo = attrs['promo']
    subsidy = attrs['ship_subsidy']
    threshold = attrs['threshold']
    weight_threshold = attrs['weight_threshold']
    items = [attrs[f'item_{i}'] for i in range(6)]
    weights = [attrs[f'weight_{i}'] for i in range(6)]
    restocks = [attrs[f'restock_{i}'] for i in range(6)]
    freights = [attrs[f'freight_{i}'] for i in range(6)]
    total_items = sum(items)
    total_weight = sum(weights)

    if (price > 1200000 or total_items < threshold
            or total_weight < weight_threshold
            or price != total_items - promo - subsidy):
        return {'feasible': False, 'utility': None}

    worst_loss = 0  # The empty event has no charges.
    for returned in _EVENTS:
        loss = (attrs['admin'] + sum(restocks[i] for i in returned)
                + max(freights[i] for i in returned))
        if total_items - sum(items[i] for i in returned) < threshold:
            loss += promo
        if total_weight - sum(weights[i] for i in returned) < weight_threshold:
            loss += subsidy
        if loss > 200000:
            return {'feasible': False, 'utility': None}
        worst_loss = max(worst_loss, loss)

    return {'feasible': True, 'utility': str(2000000 - price - worst_loss)}
